import baseline from "@/content/safety/resources/baseline.json";
import scripts from "@/content/safety/scripts.json";
import type { AgeBand, Locale, ResourceKind } from "./types";

// Reviewed fixed words: crisis scripts, redirect lines, fallbacks, steer notes and crisis resources
// (SR-14, SR-15). Never generated by a model. Per market resource files are added as data.

type Resource = { number: string | null; en: string; ar: string };
const RESOURCES: Record<string, Record<ResourceKind, Resource>> = {
  baseline: baseline.resources as Record<ResourceKind, Resource>,
};

const band = (ageBand: AgeBand): "young" | "older" => (ageBand === "10-12" ? "older" : "young");

export const SCRIPTS_VERSION = scripts.version;

export function crisisScript(key: string, locale: Locale, ageBand: AgeBand): string {
  const s = (scripts.crisis as Record<string, Record<Locale, { young: string; older: string }>>)[key];
  if (!s) throw new Error(`Unknown crisis script "${key}"`);
  return s[locale][band(ageBand)];
}

/** One of the reviewed lines, chosen at random so it doesn't sound robotic (§2.2). */
export function redirectLine(key: string, locale: Locale, pick = Math.random): string {
  const lines = (scripts.redirect as Record<string, Record<Locale, string[]>>)[key]?.[locale];
  if (!lines?.length) return fallbackLine(locale, pick);
  return lines[Math.floor(pick() * lines.length)];
}

export function fallbackLine(locale: Locale, pick = Math.random): string {
  const lines = scripts.fallback[locale];
  return lines[Math.floor(pick() * lines.length)];
}

export function steerNote(key: string): string | null {
  const v = (scripts.steer as Record<string, string>)[key];
  return key === "note" ? null : (v ?? null);
}

/** Resources for a market, falling back to the baseline (which has no phone numbers, D-059). */
export function resources(kinds: ResourceKind[], market: string, locale: Locale) {
  const set = RESOURCES[market] ?? RESOURCES.baseline;
  return kinds.map((kind) => ({ kind, text: set[kind][locale], number: set[kind].number }));
}
